    var ah = (a >>> 16) & 0xffff, al = a & 0xffff;
    var bh = (b >>> 16) & 0xffff, bl = b & 0xffff;
    return ((al * bl) + (((ah * bl + al * bh) << 16) >>> 0)) | 0;
}
function rotr(x, n) { return ((x >>> n) | (x << (32 - n))) >>> 0; }
function rol16(x) { return (((x << 16) | (x >>> 16))) >>> 0; }

