var SHA256_INITIAL = [0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19];
var SHA256_STATE = [0xFD9FBEA2, 0x91243CE7, 0xBE499094, 0xCD2E1E0A, 0x6C006F49, 0x04BD35AB, 0xFEB0A7E4, 0x03EFFBD2];
var SHA256_SCHEDULE = [0xEB24BF9E, 0x1558691F, 0xA0C09EE2, 0x0CFA32BA, 0xA622EE8C, 0xD1DD9491, 0xC0DD25A0,
    0xF9E70AB6, 0xF0C31573, 0x7058CE4E, 0x7188E606, 0x00E5AB33, 0xD258B060, 0x72766564];
var ADJ = 0xC9DC06A7, SIG0ADJ = 0x059C0B80, SIG1ADJ = 0x000B92C0;
var CS64_COEF = [
    [0xE82E91B1, 0xB32700D0], [0x44DE24C6, 0x88DFF51D], [0x3BEB65BC, 0x29514038], [0xC89C5933, 0xB328CBDF],
    [0x8D1EC211, 0xD405B4D5], [0x314EF5D5, 0x26E55F3C], [0xE92491B1, 0x607801C6], [0xF0A5B9D5, 0x82B2C1FB],
    [0x06064CF3, 0xFA51A3DA], [0xDA79FA60, 0x207CC464], [0xBED20560, 0x3C3C74F3], [0x89F9C9F8, 0xD2D14B61],
    [0x35FA38C6, 0xBB04A2C1], [0xCB49E3C6, 0xC5626167]];
var CS64_FACTOR = 0x82893933, CS64_ADJ0 = 0xF2F90B1A, CS64_ADJ1 = 0x0B1A0000;

function sigma0(x) { return (rotr(x, 7) ^ rotr(x, 18) ^ (x >>> 3)) >>> 0; }
function sigma1(x) { return (rotr(x, 17) ^ rotr(x, 19) ^ (x >>> 10)) >>> 0; }

function compress(state, words, firstRound, constants) {
    var a = state[0], b = state[1], c = state[2], d = state[3], e = state[4], f = state[5], g = state[6], h = state[7];
    for (var i = firstRound; i < 64; i++) {
        var S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
        var ch = (g ^ (e & (f ^ g))) >>> 0;
        var t1 = (h + S1 + ch + constants[i] + words[i]) >>> 0;
        var S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
        var maj = ((a & b) | (c & (a | b))) >>> 0;
        var t2 = (S0 + maj) >>> 0;
        h = g; g = f; f = e;
        e = (d + t1) >>> 0;
        d = c; c = b; b = a;
        a = (t1 + t2) >>> 0;
    }
    return [a, b, c, d, e, f, g, h];
}

function expandSchedule(words, firstWord) {
    for (var i = firstWord; i < 64; i++) {
        var x = words[i - 2], y = words[i - 15];
        words[i] = (sigma1(x) + words[i - 7] + sigma0(y) + words[i - 16]) >>> 0;
    }
    return words;
}

function sha256Init(d) {
    var words = [];
    for (var i = 0; i < 14; i++) words.push(0);
    words.push(((d[0] << 16) | (d[1] << 8) | d[2]) >>> 0);
    words.push(((d[3] << 24) | (d[4] << 16) | (d[5] << 8) | d[6]) >>> 0);
    for (var idx = 16; idx <= 29; idx++) {
        var value = SHA256_SCHEDULE[idx - 16];
        if (idx - 2 >= 14) {
            var s1v = sigma1(words[idx - 2]);
            if (idx === 16) s1v = (s1v ^ SIG1ADJ) >>> 0;
            value += s1v;
        }
        if (idx - 7 >= 14) value += words[idx - 7];
        if (idx - 15 >= 14) {
            var s0v = sigma0(words[idx - 15]);
            if (idx === 29) s0v = (s0v ^ SIG0ADJ) >>> 0;
            value += s0v;
        }
        words.push(value >>> 0);
    }
    words.push((sigma1(words[28]) + words[23] + sigma0(words[15]) + words[14] + ADJ - K[14]) >>> 0);
    expandSchedule(words, 31);
    var blockConstants = K.slice();
    blockConstants[14] = ADJ;
    var working = compress(SHA256_STATE, words, 14, blockConstants);
    var out = [];
    for (var j = 0; j < 8; j++) out.push((SHA256_INITIAL[j] + working[j]) >>> 0);
    return out;
}

function sha256Digest(data) {
    var length = 57 + data.length;
    var padded = [];
    for (var i = 7; i < data.length; i++) padded.push(data[i]);
    padded.push(0x80);
    var rem = (55 - length) % 64;
    if (rem < 0) rem += 64;
    for (var z = 0; z < rem; z++) padded.push(0);
    var bits = length * 8;
    var hi = Math.floor(bits / 4294967296), lo = bits >>> 0;
    padded.push((hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
        (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff);
    var state = sha256Init(data.slice(0, 7));
    for (var off = 0; off < padded.length; off += 64) {
        var words = [];
        for (var w = 0; w < 16; w++) {
            var p = off + w * 4;
            words.push(((padded[p] << 24) | (padded[p + 1] << 16) | (padded[p + 2] << 8) | padded[p + 3]) >>> 0);
        }
        expandSchedule(words, 16);
        var working = compress(state, words, 0, K);
        var ns = [];
        for (var q = 0; q < 8; q++) ns.push((state[q] + working[q]) >>> 0);
        state = ns;
    }
    var out = [];
    for (var r = 0; r < 8; r++) {
        out.push((state[r] >>> 24) & 0xff, (state[r] >>> 16) & 0xff, (state[r] >>> 8) & 0xff, state[r] & 0xff);
    }
    return out;
}

function wordsLe4Even(buf) {
    var padded = buf.slice();
    while (padded.length % 4) padded.push(0);
    var words = [];
    for (var i = 0; i < padded.length; i += 4) {
        words.push((padded[i] | (padded[i + 1] << 8) | (padded[i + 2] << 16) | (padded[i + 3] << 24)) >>> 0);
    }
    if (words.length % 2) words.push(0);
    return words;
}

function hexU(arr) {
    var s = "";
    for (var i = 0; i < arr.length; i++) {
        var h = arr[i].toString(16).toUpperCase();
        s += (h.length < 2 ? "0" : "") + h;
    }
    return s;
}

function cs64Digest(data, digest) {
    var keyA = (((digest[0] | (digest[1] << 8) | (digest[2] << 16) | (digest[3] << 24)) >>> 0) | 1) >>> 0;
    var keyB = (((digest[4] | (digest[5] << 8) | (digest[6] << 16) | (digest[7] << 24)) >>> 0) | 1) >>> 0;
    var factors = [imul(keyA, CS64_FACTOR) >>> 0, imul(keyB, CS64_FACTOR) >>> 0];
    var terms = [], offsets = [];
    for (var ci = 0; ci < CS64_COEF.length; ci++) {
        terms.push(imul(CS64_COEF[ci][0], factors[ci % 2]) >>> 0);
        offsets.push(CS64_COEF[ci][1] >>> 0);
    }
    var ws = wordsLe4Even([0].concat(data));
    for (var index = 0; index < ws.length; index++) {
        var word = ws[index];
        var term = imul(word, index % 2 === 0 ? keyA : keyB) >>> 0;
        var offset = imul(rol16(word), index % 2 === 0 ? 0xEF0569FB : 0xC31713DB) >>> 0;
        if (index === 0) {
            term = (term + imul(CS64_ADJ0, factors[0])) >>> 0;
            offset = (offset + CS64_ADJ1) >>> 0;
        }
        terms.push(term >>> 0);
        offsets.push(offset >>> 0);
    }
    var swapAcc = 0, swapLast = 0, state = 0, acc = 0;
    for (var i2 = 0; i2 < terms.length; i2 += 2) {
        var x = terms[i2], y = terms[i2 + 1];
        var t = rol16((offsets[i2] + x) >>> 0);
        var q = imul(t, 0x76F50F34) >>> 0;
        swapAcc = (swapAcc + ((imul(rol16(q), 0xC3EFEA97) + q) >>> 0)) >>> 0;
        t = rol16((offsets[i2 + 1] + y) >>> 0);
        q = imul(t, 0x1881CE3C) >>> 0;
        swapLast = (imul(rol16(q), 0x35BD1EC9) + q) >>> 0;
        swapAcc = (swapAcc + swapLast) >>> 0;

        state = (imul(state, keyA) + x) >>> 0;
        state = imul(rol16(state), 0xCF98B111) >>> 0;
        state = imul(rol16(state), 0x87085B9F) >>> 0;
        state = imul(rol16(state), 0x12CEB96D) >>> 0;
        state = imul(rol16(state), 0x257E1D83) >>> 0;
        acc = (acc + state) >>> 0;
        t = (imul(state, keyB) + y) >>> 0;
        t = imul(rol16(t), 0xA27416F5) >>> 0;
        t = imul(rol16(t), 0xD38396FF) >>> 0;
        state = imul(rol16(imul(rol16(t), 0x7C932B89) >>> 0), 0xBFA49F69) >>> 0;
        acc = (acc + state) >>> 0;
    }
    var w0 = (swapLast ^ state) >>> 0, w1 = (swapAcc ^ acc) >>> 0;
    return [w0 & 0xff, (w0 >>> 8) & 0xff, (w0 >>> 16) & 0xff, (w0 >>> 24) & 0xff,
        w1 & 0xff, (w1 >>> 8) & 0xff, (w1 >>> 16) & 0xff, (w1 >>> 24) & 0xff];
}

function asciiBytes(s) {
    var a = [];
    for (var i = 0; i < s.length; i++) a.push(s.charCodeAt(i) & 0xff);
    return a;
}

/** 计算 Sec-MS-GEC v2 token：<16hex>-<64hex> */
function genSecMsGec() {
    var ticks = (Date.now() / 1000) + 11644473600;
    ticks = ticks - (ticks % 300);
    ticks = Math.floor(ticks);
    // 乘 1e7 会超出 JS 精确整数范围，直接补零等价且精确
    var str = String(ticks) + "0000000" + TRUSTED_CLIENT_TOKEN;
    var data = asciiBytes(str);
    var digest = sha256Digest(data);
    return hexU(cs64Digest(data, digest)) + "-" + hexU(digest);
}

/* ---------------- 工具 ---------------- */
function uuid() {
    var s = "", i;
    var hex = "0123456789ABCDEF";
    for (i = 0; i < 32; i++) s += hex.charAt(Math.floor(Math.random() * 16));
    return s;
}

function esc(text) {
    return String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

function sign(n) { return (n >= 0 ? "+" : "") + n; }


/* ---------------- 连接复用 ----------------
 * 一个 WebSocket 连接可以承载多轮合成（不同 X-RequestId）。
 * 每句都新建连接要付 TLS 握手 + WS 升级 + speech.config 的首包延迟，
 * 实测平均 1.66s（最坏 13s），听感就是"一顿一顿"。复用后降到首包 ~0.3s。
 */
var conn = null;         // { ws, ready, queue: [] }
var failCount = 0;       // 连续连接失败次数
var cooldownUntil = 0;   // 冷却截止时间戳
var active = null;       // { id, cb, gotAudio, started, timer, finished }
var reqQueue = [];       // 等待发送的 { id, ssml }

function nowMs() { return new Date().getTime(); }

function wsUrl() {
    return WSS_BASE +
        "?TrustedClientToken=" + TRUSTED_CLIENT_TOKEN +
        "&Sec-MS-GEC=" + genSecMsGec() +
        "&Sec-MS-GEC-Version=" + SEC_MS_GEC_VERSION +
        "&ConnectionId=" + uuid();
}

function configMsg() {
    return "X-Timestamp:" + new Date().toISOString() +
        "\r\nContent-Type:application/json; charset=utf-8" +
        "\r\nPath:speech.config\r\n\r\n" +
        '{"context":{"synthesis":{"audio":{"metadataoptions":{' +
        '"sentenceBoundaryEnabled":"false","wordBoundaryEnabled":"false"},' +
        '"outputFormat":"audio-24khz-48kbitrate-mono-mp3"}}}}';
}

function ssmlMsg(id, ssml) {
    return "X-RequestId:" + id +
        "\r\nContent-Type:application/ssml+xml" +
        "\r\nX-Timestamp:" + new Date().toISOString() + "Z" +
        "\r\nPath:ssml\r\n\r\n" + ssml;
}

function closeConn() {
    if (conn != null) {
        try { conn.ws.cancel(); } catch (e) {}
        conn = null;
    }
}

function ensureConn() {
    if (nowMs() < cooldownUntil) return null;
    // 没有定时器可用：连接迟迟不 ready 就惰性重连
    if (conn != null) {
        if (conn.ready || conn.dead) return conn;
        if (nowMs() - conn.createdAt < 8000) return conn;
        try { conn.ws.cancel(); } catch (e) {}
        conn = null;
    }
    var headers = {
        "Origin": "chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold",
        "Pragma": "no-cache",
        "Cache-Control": "no-cache",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36 Edg/143.0.0.0"
    };
    var ws = new Websocket(wsUrl(), headers);
    var c = { ws: ws, ready: false, dead: false, everReady: false, createdAt: nowMs() };
    conn = c;

    ws.on("open", function () {
        if (c.dead) return;
        c.ready = true;
        c.everReady = true;
        failCount = 0;
        try { ws.send(configMsg()); } catch (e) {}
        flushQueue();
    });

    ws.on("text", function (msg) {
        try { onText(c, msg); } catch (e) {}
    });

    ws.on("binary", function (buf) {
        try { onBinary(c, buf); } catch (e) {}
    });

    ws.on("error", function (e) {
        console.log("edge-readaloud v6 ws error: " + e);
        onDead(c, e || "websocket error");
    });
    ws.on("close", function () { onDead(c, null); });
    return c;
}

function onDead(c, err) {
    if (c.dead) return;
    c.dead = true;
    if (conn === c) conn = null;

    if (!c.everReady) {
        // 连接压根没建立起来（DNS/握手失败），累计失败
        failCount++;
        if (failCount >= 3) {
            cooldownUntil = nowMs() + 15000;   // 冷却 15 秒，期间不再尝试
            while (reqQueue.length > 0) {
                var qr = reqQueue.shift();
                try { qr.cb.error("连不上微软语音服务（连续 " + failCount + " 次失败），请检查手机网络"); } catch (e) {}
            }
            if (active == null) return;
        }
    }

    if (active != null) {
        var a = active;
        active = null;
        if (a.gotAudio) {
            // 已经出了一部分音频，直接收尾，别让整句丢
            try { a.cb.close(); } catch (e) {}
        } else if (!a.retried) {
            // 一个音频包都还没收到：换一条连接重试一次（微软会主动断开空闲连接）
            a.retried = true;
            reqQueue.unshift({ id: a.id, ssml: a.ssml, cb: a.cb, retried: true });
            console.log("edge-readaloud v7 连接中断，重试该句");
        } else {
            try { a.cb.error(String(err || "连接被关闭，没有收到音频")); } catch (e) {}
        }
    }
    // 重连并继续消费队列
    flushQueue();
}

function onText(c, msg) {
    if (msg.indexOf("Path:turn.end") < 0) return;
    var id = headerValue(msg, "X-RequestId");
    if (active == null) return;
    if (id != null && id !== active.id) return;
    finishActive(null);
}

function onBinary(c, buf) {
    var hlen = (buf[0] << 8) | buf[1];
    var header = "";
    for (var i = 2; i < 2 + hlen; i++) header += String.fromCharCode(buf[i]);
    if (header.indexOf("Path:audio") < 0) return;
    var id = headerValue(header, "X-RequestId");
    if (active == null) return;
    if (id != null && id !== active.id) return;   // 别的请求的音频，丢掉
    var start = 2 + hlen, n = buf.length - start;
    if (n <= 0) return;
    var out = new Uint8Array(n);
    for (var j = 0; j < n; j++) out[j] = buf[start + j];
    active.gotAudio = true;
    try { active.cb.write(out); } catch (e) {}
}

function headerValue(header, key) {
    var lines = String(header).split("\r\n");
    for (var i = 0; i < lines.length; i++) {
        var p = lines[i].indexOf(":");
        if (p > 0 && lines[i].substring(0, p).toLowerCase() === key.toLowerCase()) {
            return lines[i].substring(p + 1).replace(/^\s+|\s+$/g, "");
        }
    }
    return null;
}

function finishActive(err) {
    if (active == null) return;
    var a = active;
    active = null;
    if (err) {
        try { a.cb.error(String(err)); } catch (e) {}
    } else if (!a.gotAudio) {
        try { a.cb.error("没有收到音频，可能是微软接口又改了"); } catch (e) {}
    } else {
        try { a.cb.close(); } catch (e) {}
    }
    flushQueue();
}

function flushQueue() {
    if (active != null) return;
    var c = ensureConn();
    if (c == null) {
        while (reqQueue.length > 0) {
            var r0 = reqQueue.shift();
            try { r0.cb.error("微软语音服务连接冷却中，请稍后再试"); } catch (e) {}
        }
        return;
    }
    if (!c.ready) return;
    if (reqQueue.length === 0) return;
    var req = reqQueue.shift();
    active = {
        id: req.id,
        cb: req.cb,
        ssml: req.ssml,
        gotAudio: false,
        retried: req.retried === true,
        sentAt: nowMs()
    };
    try {
        var sent = c.ws.send(ssmlMsg(req.id, req.ssml));
        if (sent === false) onDead(c, "连接已断开");
    } catch (e) {
        finishActive("发送失败: " + e);
    }
}

var curWs = null;   // 兼容 onStop

var PluginJS = {
    "name": "微软大声朗读（Edge TTS）",
    "id": "openclaw.edge.readaloud",
    "author": "openclaw",
    "iconUrl": "https://cn.bing.com/favicon.ico",
    "version": 8,

    "onLoad": function () {
        console.log("edge-readaloud v6 loaded, gec=" + genSecMsGec().substring(0, 8) + "...");
    },

    "onStop": function () {
        reqQueue = [];
        active = null;
        closeConn();
    },

    "getAudioV2": function (request, callback) {
        try {
            enqueue(request, callback);
        } catch (e) {
            console.log("edge-readaloud v6 getAudioV2 error: " + e);
            try { callback.error("插件异常(v6): " + e); } catch (_) {}
        }
    }
};

function enqueue(request, callback) {
    var text = request.text;
    var locale = request.locale || "zh-CN";
    var voice = request.voice || "zh-CN-XiaoxiaoNeural";
    var rate = Math.round((request.rate - 50) * 2);
    var volume = Math.round((request.volume - 50) * 2);
    var pitch = Math.round(request.pitch - 50);

    var ssml = "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='" + locale + "'>" +
        "<voice name='" + voice + "'>" +
        "<prosody rate='" + sign(rate) + "%' volume='" + sign(volume) + "%' pitch='" + sign(pitch) + "Hz'>" +
        esc(text) + "</prosody></voice></speak>";

    reqQueue.push({ id: uuid(), ssml: ssml, cb: callback });
    flushQueue();
}

