                fs.writeFile("voices.json", jsonStr);
            }
            voicesCache = JSON.parse(jsonStr);
        } catch (e) {
            console.log("拉取音色列表失败，使用内置列表：" + e);
            voicesCache = null;
        }
    },

    "getLocales": function () {
        var set = {}, out = [];
        if (voicesCache != null) {
            for (var i = 0; i < voicesCache.length; i++) {
                var l = voicesCache[i].Locale;
                if (!set[l]) { set[l] = 1; out.push(l); }
            }
            out.sort();
            if (out.length > 0) return out;
        }
        for (var k in FALLBACK_VOICES) out.push(k);
        return out;
    },

    "getVoices": function (locale) {
        var map = {};
        if (voicesCache != null) {
            for (var i = 0; i < voicesCache.length; i++) {
                var v = voicesCache[i];
                if (v.Locale !== locale) continue;
                map[v.ShortName] = {
                    name: v.FriendlyName ? v.FriendlyName.replace("Microsoft ", "").replace(" Online (Natural)", "") : v.ShortName,
                    icon: v.Gender === "Female" ? "female" : "male"
                };
            }
            if (Object.keys(map).length > 0) return map;
        }
        return FALLBACK_VOICES[locale] || { "zh-CN-XiaoxiaoNeural": { name: "晓晓", icon: "female" } };
    },

    "onVoiceChanged": function (locale, voiceCode) { }
};
